import json

# Generate 17x17 output with full pattern
# The pattern: d=6 boundary gets 2, d=2 and d=4 get 1, d=0 gets 0

H, W = 17, 17
center_r, center_c = 8, 8

grid = [[0] * W for _ in range(H)]

for r in range(H):
    for c in range(W):
        d = abs(r - center_r) + abs(c - center_c)

        if d == 6:
            grid[r][c] = 2
        elif d == 2:
            grid[r][c] = 1
        elif d == 4:
            grid[r][c] = 1
        elif d == 0:  # center
            grid[r][c] = 0

print("17x17 grid:")
for row in grid:
    print(row)

# Verify count of each value
vals = {}
for row in grid:
    for val in row:
        vals[val] = vals.get(val, 0) + 1
print(f"\nValue counts: {vals}")

# Count cells by d
for d in range(8):
    count = sum(1 for r in range(H) for c in range(W) if abs(r-center_r)+abs(c-center_c)==d)
    print(f"d={d}: {count} cells")

